import 'package:angular/angular.dart';
import 'package:angular_bloc/angular_bloc.dart';
import 'package:bloc/bloc.dart';

class CounterCubit extends Cubit<int> {
  CounterCubit() : super(0);
  void increment() => emit(state + 1);
}

@Component(
  selector: 'counter-page',
  template: '''
    <h2>Count: {{ $pipe.bloc(counterCubit) }}</h2>
    <button (click)="counterCubit.increment()">+</button>
  ''',
  pipes: [BlocPipe],
)
class CounterPageComponent implements OnInit, OnDestroy {
  late final CounterCubit counterCubit;
  void ngOnInit() => counterCubit = CounterCubit();
  void ngOnDestroy() => counterCubit.close();
}
